import org.jsoup.Connection;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.runners.MockitoJUnitRunner;
import java.net.URL;
import java.net.MalformedURLException;
import java.io.UnsupportedEncodingException;

import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    Connection.KeyVal keyVal;

    @Test
    public void urlBuilderConstructorTest() throws MalformedURLException {
        URL inputUrl = new URL("https://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertNotNull(urlBuilder);
    }

    @Test
    public void buildTest() throws MalformedURLException {
        URL inputUrl = new URL("https://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL builtUrl = urlBuilder.build();
        assertEquals(inputUrl, builtUrl);
    }

    @Test
    public void appendKeyValTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("https://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        doReturn("key").when(keyVal).key();
        doReturn("value").when(keyVal).value();
        urlBuilder.appendKeyVal(keyVal);
        URL builtUrl = urlBuilder.build();
        assertEquals(new URL("https://example.com?key=value"), builtUrl);
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValUnsupportedEncodingTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("https://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        doReturn("invalid$$").when(keyVal).key(); 
        urlBuilder.appendKeyVal(keyVal); 
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValEmptyKeyTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("https://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        doReturn("").when(keyVal).key(); 
        urlBuilder.appendKeyVal(keyVal); 
    }
}
```
